syntax:
// default values are written in the PROTOTYPE, on the right-most parameters
double area(double r, double pi = 3.14159);        // pi is optional
int fare(int km, int rate = 30, int booking = 50);  // rate and booking optional

// the definition does NOT repeat the defaults
double area(double r, double pi) {
    return pi * r * r;
}

// calls
area(2);          // pi = 3.14159 (default)
area(2, 3.14);    // pi = 3.14 (caller)
fare(10, 40);     // rate = 40, booking = 50 (default)

sample.code:
#include <iostream>
using namespace std;

double area(double r, double pi = 3.14159);

int main() {
    cout << area(2) << endl;
    cout << area(2, 3.14) << endl;
    return 0;
}

double area(double r, double pi) {
    return pi * r * r;
}

#include <iostream>
using namespace std;

int fare(int km, int rate = 30, int booking = 50);

int main() {
    cout << fare(10) << endl;
    cout << fare(10, 40) << endl;
    cout << fare(10, 40, 0) << endl;
    return 0;
}

int fare(int km, int rate, int booking) {
    return km * rate + booking;
}

#include <iostream>
using namespace std;

void printLine(char ch = '*', int n = 10);

int main() {
    int n;
    cin >> n;
    printLine();
    printLine('-');
    printLine('#', n);
    return 0;
}

void printLine(char ch, int n) {
    for (int i = 0; i < n; i++) {
        cout << ch;
    }
    cout << endl;
}

